"""Create a visual style selector from local poster/video pairs."""
from pathlib import Path
import argparse,html,json,os
from urllib.parse import quote
def build(catalog,output):
    spec=json.loads(catalog.read_text(encoding="utf-8"));root=catalog.resolve().parent
    rows=[];cards=[]
    for i,s in enumerate(spec["styles"]):
        poster=(root/s["poster"]).resolve();video=(root/s["video"]).resolve()
        assert poster.is_file() and video.is_file(),"Missing style preview"
        uri=quote(os.path.relpath(poster,output.resolve().parent).replace("\\","/"),safe="/.")
        video_uri=quote(os.path.relpath(video,output.resolve().parent).replace("\\","/"),safe="/.")
        rows.append({k:s[k] for k in ("id","name","description")})
        cards.append(f'''<article class="card" id="card-{i}"><div class="shot"><img class="still" src="{uri}" alt="{html.escape(s['name'])} representative shot"><video class="grid-preview" autoplay muted loop preload="metadata" playsinline aria-hidden="true" tabindex="-1" disablepictureinpicture poster="{uri}" src="{video_uri}"></video><span class="loop-label">Muted loop</span><button class="preview" data-index="{i}" aria-label="Preview {html.escape(s['name'])}"><svg class="icon" viewBox="0 0 24 24" width="16" height="16" fill="currentColor" aria-hidden="true"><path d="m8 5 11 7-11 7z"/></svg>Play narrated preview</button></div><div class="details"><div class="card-title"><h2>{html.escape(s['name'])}</h2><span class="badge">1080p</span></div><p>{html.escape(s['description'])}</p><button class="select" data-index="{i}" aria-pressed="false">Select {html.escape(s['name'])}<span aria-hidden="true"><svg class="icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M6 18 18 6M6 6h12v12"/></svg></span></button><a class="review-settings" href="#settings-heading">Review settings &amp; copy</a></div></article>''')
    data=json.dumps(rows,ensure_ascii=False).replace("<","\\u003c")
    doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Explainer Studio &middot; Style selector</title><style>
    :root{color-scheme:dark;--ink:#eef3fb;--muted:#a4afc4;--accent:#b5f2d5}*{box-sizing:border-box}body{margin:0;background:#0b1019;color:var(--ink);font:16px/1.5 system-ui,sans-serif}main{max-width:1440px;margin:auto;padding:42px 42px 60px}.mast{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #273246;padding-bottom:20px}.brand{font-weight:650;letter-spacing:.03em}.dot{display:inline-block;background:var(--accent);width:11px;height:11px;margin-right:12px;border-radius:3px}.edition{font-size:12px;color:var(--muted);letter-spacing:.12em}.intro{display:flex;align-items:end;justify-content:space-between;gap:32px;margin:36px 0 30px}h1{font-size:clamp(32px,4vw,52px);font-weight:550;letter-spacing:-.04em;margin:0 0 9px}.intro p{color:var(--muted);max-width:700px;margin:0}.sample{flex-shrink:0;color:var(--accent);font-size:13px;padding-bottom:4px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.card{border:1px solid #2a3547;border-radius:17px;overflow:hidden;background:#141c29;transition:border-color .2s,box-shadow .2s}.card.chosen{border-color:var(--accent);box-shadow:0 0 0 2px #b5f2d522}.shot{position:relative;background:#080c16}.shot video{width:100%;aspect-ratio:16/9;display:block}.number{position:absolute;top:14px;left:14px;font:12px/1 monospace;background:#0b1019cc;border:1px solid #ffffff33;border-radius:5px;padding:7px;color:white;pointer-events:none}.details{padding:22px}.card-title{display:flex;justify-content:space-between;align-items:center}h2{font-size:24px;letter-spacing:-.02em;margin:0}.badge{font:11px monospace;color:var(--muted);border:1px solid #344054;border-radius:4px;padding:4px 7px}.details p{min-height:48px;color:var(--muted);font-size:14px;margin:10px 0 21px}.select{width:100%;display:flex;justify-content:space-between;background:#202c3f;color:var(--ink);border:1px solid #42516a;padding:14px 16px;border-radius:9px;font:600 14px system-ui;cursor:pointer}.select:hover{background:#2a3a51}.select[aria-pressed=true]{background:var(--accent);color:#123328;border-color:var(--accent)}button:focus-visible,a:focus-visible{outline:3px solid #b5f2d5;outline-offset:4px}.selection{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-top:26px;padding:22px 24px;border:1px solid #2a3547;border-radius:13px;background:#101925}.selection h3{font-size:16px;margin:0 0 5px}.selection p{font-size:13px;color:var(--muted);margin:0;max-width:820px}.foot{font-size:12px;color:#8390a6;margin-top:22px}.prompt{font-family:monospace;color:#cde6db!important;margin-top:8px!important}[hidden]{display:none!important}@media(min-width:1250px){.grid{grid-template-columns:repeat(2,1fr)}.details{padding:18px}.card-title h2{font-size:22px}.details p{min-height:84px}}@media(max-width:850px){main{padding:22px 18px}.intro{display:block}.sample{margin-top:18px}.grid{grid-template-columns:1fr}.selection{align-items:start;flex-direction:column}.edition{display:none}}
    </style></head><body><main><header class="mast"><div class="brand"><span class="dot"></span>EXPLAINER STUDIO</div><div class="edition">STYLE LIBRARY / 01</div></header><section class="intro"><div><h1>Choose how your story looks.</h1></div></section><section class="grid">'''+''.join(cards)+'''</section><p class="foot">Representative shots rendered from the reusable style packs. Choices are remembered in this browser. Use Copy settings to clipboard, then paste into your chat.</p></main><script>const styles='''+data+''';
'''+(Path(__file__).resolve().parents[1]/'assets/selector/settings.js').read_text(encoding='utf-8')+'''
    </script></body></html>'''
    doc=doc.replace('</style>',(Path(__file__).resolve().parents[1]/'assets/selector/media.css').read_text(encoding='utf-8')+'</style>')
    doc=doc.replace('Choose how your story looks.',html.escape(spec.get("title","Choose how your story looks.")))
    selector=Path(__file__).resolve().parents[1]/"assets/selector"
    doc=doc.replace('<section class="grid">', (selector/'settings.html').read_text(encoding='utf-8')+'<h2 class="library-title">Choose your style</h2><section class="grid">')
    doc=doc.replace('</style>',(selector/'settings.css').read_text(encoding='utf-8')+'</style>')
    doc=doc.replace('</main>','</main>'+(selector/'media.html').read_text(encoding='utf-8'))
    doc=doc.replace('</script>',(selector/'credentials.js').read_text(encoding='utf-8')+(selector/'media.js').read_text(encoding='utf-8')+'</script>')
    output.parent.mkdir(parents=True,exist_ok=True);output.write_text(doc,encoding="utf-8");print(output)
if __name__=="__main__":
    a=argparse.ArgumentParser();a.add_argument("catalog",type=Path);a.add_argument("output",type=Path);args=a.parse_args();build(args.catalog,args.output)
